CREATE TABLE IF NOT EXISTS creator_hub_profiles (user_id integer PRIMARY KEY, role text NOT NULL DEFAULT 'creator', verification_state text NOT NULL DEFAULT 'unverified', display_name text NOT NULL, bio text NOT NULL DEFAULT '', created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS creator_applications (id serial PRIMARY KEY, user_id integer NOT NULL, status text NOT NULL DEFAULT 'pending', portfolio_url text, notes text NOT NULL DEFAULT '', reviewed_by integer, reviewed_at bigint, created_at bigint NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS creator_applications_pending_idx ON creator_applications(user_id) WHERE status='pending';
CREATE INDEX IF NOT EXISTS creator_applications_user_status_idx ON creator_applications(user_id,status);
CREATE TABLE IF NOT EXISTS business_verifications (id serial PRIMARY KEY, user_id integer NOT NULL, status text NOT NULL DEFAULT 'pending', legal_name text NOT NULL, tax_id_last4 text, document_object_paths jsonb NOT NULL DEFAULT '[]', reviewed_by integer, reviewed_at bigint, created_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS business_verifications_user_status_idx ON business_verifications(user_id,status);
CREATE TABLE IF NOT EXISTS creator_hub_products (id serial PRIMARY KEY, business_user_id integer NOT NULL, slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK(price_cents >= 0), currency text NOT NULL DEFAULT 'usd', inventory integer NOT NULL DEFAULT 0 CHECK(inventory >= 0), active boolean NOT NULL DEFAULT true, image_object_paths jsonb NOT NULL DEFAULT '[]', created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS creator_hub_products_owner_idx ON creator_hub_products(business_user_id,active);
CREATE TABLE IF NOT EXISTS creator_hub_campaigns (id serial PRIMARY KEY, product_id integer NOT NULL, business_user_id integer NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', commission_bps integer NOT NULL DEFAULT 1000 CHECK(commission_bps >= 1000 AND commission_bps <= 10000), status text NOT NULL DEFAULT 'draft', starts_at bigint, ends_at bigint, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS creator_hub_campaigns_owner_idx ON creator_hub_campaigns(business_user_id,status);
CREATE TABLE IF NOT EXISTS creator_product_approvals (id serial PRIMARY KEY, product_id integer NOT NULL, campaign_id integer, creator_user_id integer NOT NULL, status text NOT NULL DEFAULT 'pending', referral_slug text UNIQUE, reviewed_at bigint, created_at bigint NOT NULL);
ALTER TABLE creator_product_approvals ADD COLUMN IF NOT EXISTS commission_bps integer NOT NULL DEFAULT 1000;
CREATE UNIQUE INDEX IF NOT EXISTS creator_product_approvals_unique_idx ON creator_product_approvals(product_id,campaign_id,creator_user_id);
CREATE TABLE IF NOT EXISTS post_product_attachments (id serial PRIMARY KEY, post_id integer NOT NULL, product_id integer NOT NULL, creator_user_id integer NOT NULL, created_at bigint NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS post_product_attachments_unique_idx ON post_product_attachments(post_id,product_id);
CREATE TABLE IF NOT EXISTS affiliate_clicks (id serial PRIMARY KEY, product_id integer NOT NULL, creator_user_id integer, referral_slug text, visitor_hash text, created_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS affiliate_clicks_product_created_idx ON affiliate_clicks(product_id,created_at);
CREATE TABLE IF NOT EXISTS creator_hub_carts (id serial PRIMARY KEY, user_id integer NOT NULL, status text NOT NULL DEFAULT 'open', created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS creator_hub_carts_user_open_idx ON creator_hub_carts(user_id) WHERE status='open';
CREATE TABLE IF NOT EXISTS creator_hub_cart_items (id serial PRIMARY KEY, cart_id integer NOT NULL, product_id integer NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), created_at bigint NOT NULL);
ALTER TABLE creator_hub_cart_items ADD COLUMN IF NOT EXISTS referral_slug text;
ALTER TABLE creator_hub_cart_items ADD COLUMN IF NOT EXISTS creator_user_id integer;
CREATE UNIQUE INDEX IF NOT EXISTS creator_hub_cart_items_unique_idx ON creator_hub_cart_items(cart_id,product_id);
CREATE TABLE IF NOT EXISTS creator_hub_orders (id serial PRIMARY KEY, buyer_user_id integer NOT NULL, status text NOT NULL DEFAULT 'pending', total_cents integer NOT NULL CHECK(total_cents >= 0), currency text NOT NULL DEFAULT 'usd', idempotency_key text NOT NULL, payment_intent_id text UNIQUE, shipping_address jsonb, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS creator_hub_orders_idempotency_idx ON creator_hub_orders(buyer_user_id,idempotency_key);
CREATE INDEX IF NOT EXISTS creator_hub_orders_buyer_idx ON creator_hub_orders(buyer_user_id,created_at);
CREATE TABLE IF NOT EXISTS creator_hub_order_items (id serial PRIMARY KEY, order_id integer NOT NULL, product_id integer NOT NULL, business_user_id integer NOT NULL, creator_user_id integer, referral_slug text, quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents integer NOT NULL, commission_bps integer NOT NULL CHECK(commission_bps >= 1000), commission_cents integer NOT NULL, fulfillment_status text NOT NULL DEFAULT 'unfulfilled', tracking_number text, shipped_at bigint, delivered_at bigint);
CREATE INDEX IF NOT EXISTS creator_hub_order_items_order_idx ON creator_hub_order_items(order_id);
CREATE INDEX IF NOT EXISTS creator_hub_order_items_creator_idx ON creator_hub_order_items(creator_user_id,fulfillment_status);
CREATE TABLE IF NOT EXISTS creator_hub_reviews (id serial PRIMARY KEY, order_item_id integer NOT NULL UNIQUE, product_id integer NOT NULL, buyer_user_id integer NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL DEFAULT '', created_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS creator_hub_payouts (id serial PRIMARY KEY, order_item_id integer NOT NULL UNIQUE, creator_user_id integer NOT NULL, amount_cents integer NOT NULL, status text NOT NULL DEFAULT 'pending', paid_at bigint, created_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS creator_hub_payouts_creator_status_idx ON creator_hub_payouts(creator_user_id,status);